__NUXT_JSONP__("/tr/westwood", (function(a){return {data:[{details:{slug:a,pageTitle:"Westwood Kampüsü | Mentor Language Institute",pageDescription:"Westwood, Los Angeles’ın batı tarafında yer alan canlı ve eşsiz bir semttir. ",title:"Westwood Kampüsü",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FfsCjSV4E_l0",subtitle:["Westwood, Los Angeles’ın batı tarafında yer alan canlı ve eşsiz bir semttir.","Westwood UCLA'nın evi olmakla ünlüdür. Westwood kampüsü Wilshire Blvd ve Westwood Bulvarı üzerinde yer almaktadır. Wilshire Blvd ve Westwood Blvd'deki ana otobüs hattından sadece 1 dakika uzaklıktadır.","Pek çok mağaza, restoran ve takılmak için güvenli yerler olduğu için öğrenciler ve ofis çalışanları için çok eğlenceli ve popüler bir alandır."],landmark:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fsanta-monica.jpg",title:"Otobüsle Santa Monica'ya 20 dakika"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fbeverly-hills.jpg",title:"Otobüsle Beverly Hills'e 10 dakika"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Flos-angeles-skyline.jpg",title:"Downtown LA otobüsle 60 dakika"}],gallery:{title:"Westwood Kampüsü Fotoğraf Galerisi",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002F10880-building.jpg",title:"Binanın birinci katındadır.",subtitle:"Derse gitmek için asansör'e binmenize gerek yok."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffront-desk.jpg",title:"Danışma"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fclassroom.jpg",title:"Sınıflar"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fcomputer-room.jpg",title:"Bilgisayar odası"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fstudent-lounge.jpg",title:"Öğrenci salonu"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffree-space.jpg",title:"Boş alan"}]},location:{title:"Konum",map_link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3305.4289041796537!2d-118.44512238478478!3d34.05851788060419!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bb7e2b42fadf%3A0xad96227841e11efb!2s10880+Wilshire+Blvd%2C+Los+Angeles%2C+CA+90024!5e0!3m2!1sen!2sus!4v1513884279258"},video:[{title:"1. Otobüs ile MLI Westwood Campus konumuna nasıl gidilir?",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV2zydV7aWvA"},{title:"2. MLI Westwood Kampüsüne Araba ile Nasıl Gidilir?",space:"\u003Cbr\u002F\u003E",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F5FXkkyV3DZg"}],environment:{title:"Çevre",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fucla.jpg",title:"UCLA ile yürüme mesafesinde."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fhammer-museum.jpg",title:"LA'daki en ünlü müzelerden olan Hammer Müzesi, kampüsümüzün hemen yanında."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-library.jpg",title:"Kampüsün arkasında çalışabileceğiniz bir kütüphane var."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fchevron-restaurant.jpg",title:"Uygun fiyatlı birçok restoran var."}]},accommodation:{title:"Konaklama",description:["Konaklamalarınız için aile yanı veya yurt seçenekleri sunuyoruz."],types:[{desc:["＜Yurt＞\u003Cbr \u002F\u003E Öğrenci yurdunda 40 oda bulunmaktadır ve okula yürüyerek ya da otobüsle ulaşabilirsiniz."],yt_link2:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV_eNdjw6Z1c"},{desc:["＜Homestay＞"],other_desc:["Aile yanı, Amerikan kültürü hakkında bilgi edinmenin ve İngilizce konuşma fırsatlarınızı artırmanın en iyi yoludur.","\u003Ca href=\"\u002Ftr\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E Konaklama hakkında daha fazla bilgi\u003C\u002Fa\u003E"]}]},courses:{title:"Dersler",lists:["ESL Program","TOEFL®","IELTS™","Konuşma Programı","TOEIC®"]},message:{title:"Westwood Kampüsünden Mesaj",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-director.jpg",position:"Kampüs Direktörünün Mesajı",description:["Westwood kampüsü, UCLA'nın yakınındaki harika bir bölgede yer almaktadır. Film, alışveriş ve müze gibi ziyaret edilecek çeşitli yerler var. Birçok Westwood öğrencisi Üniversite çalışmalarını sürdürürken bu yerleri ziyaret ediyor. TOEFL® kursumuz çok popülerdir. Ayrıca, derslerimiz ve çalışma politikamız şaşırtıcı derecede mantıklı. Birçok kişi MLI'ya diğer okullardan transfer oluyor!"]},dir:"\u002Fwestwood",path:"\u002Fwestwood\u002Ftr",extension:".json",createdAt:"2026-10-22T16:31:31.446Z",updatedAt:"2025-05-26T12:06:28.049Z"},lang:a}],fetch:{},mutations:void 0}}("tr")));